  Lemma z4e_src : forall m, z4e_srcp m0 -> munch DW m0 m -> z4e_srcp m.
Proof using All.
  unfold z4e_srcp. z4e_sb z4s_src.
Qed.

  (* [comment removed for export] *)
  Lemma z4e_out : forall m, wmono bsegs m0 m ->
    (DST = 0 /\ dcap = 0) \/ (exists buf, u8arr bsegs m DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap).
Proof using All.
  z4e_sb z4s_out.
Qed.

  Lemma z4_stk_ext : forall m lo' A cs hi, stk bsegs m lo' A -> rw_cells bsegs m A cs -> lo' <= A ->
    hi = A + Z.of_nat (cells_size cs) -> stk bsegs m lo' hi.
Proof.
  intros m lo' A cs hi ST RW LE ->. eapply stk_merge; [exact ST | exact (stk_of_rw_cells _ _ _ _ RW) | lia].
Qed.

  Ltac z4e_stk_merge STK FF0 FF1 FS1 FF2 FS2 FRA :=
    let T1 := fresh "T" in let T2 := fresh "T" in let T3 := fresh "T" in let T4 := fresh "T" in let T5 := fresh "T" in
    pose proof (z4_stk_ext _ _ _ _ (SP + -456) STK FF0 ltac:(lia) ltac:(cbn [cells_size csize]; lia)) as T1;
    pose proof (z4_stk_ext _ _ _ _ (SP + -440) T1 FF1 ltac:(lia) ltac:(cbn [cells_size csize]; lia)) as T2;
    pose proof (z4_stk_ext _ _ _ _ (SP + -280) T2 FS1 ltac:(lia) ltac:(cbn [cells_size csize]; lia)) as T3;
    pose proof (z4_stk_ext _ _ _ _ (SP + -264) T3 FF2 ltac:(lia) ltac:(cbn [cells_size csize]; lia)) as T4;
    pose proof (z4_stk_ext _ _ _ _ (SP + -256) T4 FS2 ltac:(lia) ltac:(cbn [cells_size csize]; lia)) as T5;
    exact (z4_stk_ext _ _ _ _ (SP + -104) T5 FRA ltac:(lia) ltac:(cbn [cells_size csize]; lia)).

  Lemma z4e_d0 : 0 <= DST /\ DST + dcap <= ATOP /\ (DST + dcap <= 0x7fff7000 \/ 0x10007fff8000 <= DST).
Proof using All.
  z4e_sb z4s_d0.
Qed.

