  (* [comment removed for export] *)
  Lemma z4e_epi : forall mm (t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6 xra : word),
    stk bsegs mm lo (SP + -104) -> rw_cells bsegs mm (SP + -104) FRS ->
    mem_inv bsegs mm -> munch DW m0 mm -> wmono bsegs m0 mm ->
    evtF bsegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7
                                 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6) FR (Z_to_bv 64 AZ4_EPI) fc None mm (seg_rom bsegs)).
Proof using All.
  intros mm t0 t1 t2 x8 x9 a0 a1 a2 a3 a4 a5 a6 a7 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6 xra ST FRB MI MU WM.
  pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
  unfold AZ4_EPI.
  do 13 zstep. zstep. zstep.
  release_frame FRB ST (bv_unsigned sp).
  apply evtF_done. unfold huf_dec_postA.
  try (lazymatch goal with |- context [Z_to_bv 64 (bv_unsigned sp + ?k + ?k')] =>
         replace (bv_unsigned sp + k + k') with (bv_unsigned sp) by lia end).
  rewrite ?Z_to_bv_bv_unsigned.
  do 16 eexists. split; [reflexivity|].
  split; [exact MI|]. split; [exact ST|]. split; [apply z4e_magree; assumption | apply z4e_aheap; assumption].
Qed.

  Lemma z4e_dcall : forall mm (junk : list byte)
      (x1 x5 x6 x7 x8 x9 x10 x11 x15 x16 x17 x18 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word),
    bytes_at bsegs mm SS (map (Z_to_bv 8) src) -> bytes_at bsegs mm (DT + 4) cbs ->
    bytes_at bsegs mm DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    rw_cells bsegs mm SPF [CB 424 junk] -> rw_cells bsegs mm (SP + -104) FRS -> stk bsegs mm lo SPF ->
    mem_inv bsegs mm -> munch DW m0 mm -> wmono bsegs m0 mm ->
    evtF bsegs RNG POST (MS (mkR x1 (Z_to_bv 64 SPF) gp tp x5 x6 x7 x8 x9 x10 x11 (Z_to_bv 64 SS) (Z_to_bv 64 n)
                                 (Z_to_bv 64 DT) x15 x16 x17 x18 (Z_to_bv 64 dcap) (Z_to_bv 64 DST) x21 x22 x23 x24 x25 x26
                                 x27 x28 x29 x30 x31)
                            FR (Z_to_bv 64 (AZ4_DRET - 12)) fc None mm (seg_rom bsegs)).
Proof using All.
  intros mm junk x1 x5 x6 x7 x8 x9 x10 x11 x15 x16 x17 x18 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31
    SRC1 CBS1 HDR1 JNK FRB STK MI MU WM.
  pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
  pose proof z4e_d0 as (D0 & D1 & _).
  unfold HUF_DEC_STACK_A in LOS.
  assert (USP : bv_unsigned (Z_to_bv 64 SPF) = SPF) by (apply unsigned_lit; lia).
  pose proof (SLOWD AI L RNG st LB rng_fs (Z_to_bv 64 AZ4_DRET) (Z_to_bv 64 SPF) gp tp x8 x9 x18 (Z_to_bv 64 dcap)
                (Z_to_bv 64 DST) x21 x22 x23 x24 x25 x26 x27 FR fc mm DST dcap SS DT mtl tl lo src cells cbs pdt SBL SBH rstk)
    as DC0.
  rewrite USP in DC0.
  specialize (DC0 (z4e_aheap mm MU WM) NFK ABL MTL TLM HDT TOK ECB LCB DSTF DC BYS NSM S16 SRCB
                  ltac:(unfold KXGoM.apart in *; lia) ltac:(unfold KXGoM.apart in *; lia) ltac:(unfold KXGoM.apart in *; lia)
                  LOA ltac:(unfold Z4D_STACK; lia) ltac:(lia) ltac:(Z.div_mod_to_equations; lia) TPA I
                  (z4e_rclean mm MU WM) RLO ltac:(lia) RRL RRS WSK WIM WIS WFS).
  unfold z4d_goal in DC0.
  match goal with |- context [Z_to_bv 64 (?a - 12)] => let v := eval vm_compute in (a - 12) in change (a - 12) with v end.
  zstep. zstep. zstep.
  eapply evtF_cut; [eapply DC0; [exact (z4e_out mm WM) | exact SRC1 | exact CBS1 | exact HDR1 | rewrite USP; exact STK
                                | exact MI] |].
  cbv beta. intros ms' P. unfold z4d_postA in P.
  destruct P as (t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & m' & -> & MI' & STK' & MU' & WM').
  rewrite USP in STK', MU'.
  rewrite (ret_pc_even AZ4_DRET); [| unfold AZ4_DRET; lia | reflexivity].
  change (Z_to_bv 64 AZ4_DRET) with (Z_to_bv 64 AZ4_EPI) at 2.
  pose proof (rw_cells_transport _ _ _ _ _ _ FRB MU' WM') as FRB'.
  cbn [disjoint_from cells_size csize Nat.add] in FRB'. specialize (FRB' ltac:(repeat split; lia)).
  pose proof (rw_cells_transport _ _ _ _ _ _ JNK MU' WM') as JNK'.
  cbn [disjoint_from cells_size csize Nat.add] in JNK'. specialize (JNK' ltac:(repeat split; lia)).
  pose proof (stk_of_rw_cells bsegs m' _ _ JNK') as SK. cbn [cells_size csize Nat.add] in SK.
  apply z4e_epi.
  - eapply stk_merge; [exact STK' | replace (bv_unsigned sp + -104) with (SPF + Z.of_nat 424) by lia; exact SK | lia].
  - exact FRB'.
  - exact MI'.
  - eapply munch_trans; [exact MU |].
    eapply munch_weaken; [| exact MU']. intros x X. cbn [outside] in X |- *. destruct X as (X1 & X2 & _).
    split; [lia | split; [exact X2 | exact I]].
  - eapply wmono_trans; [exact WM | exact WM'].
Qed.

  Ltac z4e_to t1 t2 :=
    repeat (lazymatch goal with
            | |- evtF _ _ _ (MS _ _ (Z_to_bv 64 t1) _ _ _ _) => fail
            | |- evtF _ _ _ (MS _ _ (Z_to_bv 64 t2) _ _ _ _) => fail
            | _ => first [ zstep | let K := fresh "K" in if_cases K; zify_cond K; try (exfalso; lia) ]
            end).

  Lemma z4e_nofast : forall mm (junk : list byte) (r : Z)
      (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word),
    (r = 0 \/ r = 2^64 - 20) ->
    bytes_at bsegs mm SS (map (Z_to_bv 8) src) -> bytes_at bsegs mm (DT + 4) cbs ->
    bytes_at bsegs mm DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    rw_cells bsegs mm SPF [CB 424 junk] -> rw_cells bsegs mm (SP + -104) FRS -> stk bsegs mm lo SPF ->
    mem_inv bsegs mm -> munch DW m0 mm -> wmono bsegs m0 mm ->
    evtF bsegs RNG POST (MS (mkR x1 (Z_to_bv 64 SPF) gp tp x5 x6 x7 (Z_to_bv 64 DT) (Z_to_bv 64 n) (Z_to_bv 64 r) x11 x12
                                 x13 x14 x15 x16 x17 (Z_to_bv 64 SS) (Z_to_bv 64 dcap) (Z_to_bv 64 DST) x21 x22 x23 x24 x25
                                 x26 x27 x28 x29 x30 x31)
                            FR (Z_to_bv 64 (AHUF_DX2_4X + 220)) fc None mm (seg_rom bsegs)).
Proof using All.
  intros mm junk r x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31
    HR SRC1 CBS1 HDR1 JNK FRB STK MI MU WM.
  pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
  assert (SK : stk bsegs mm lo (SP + -104)).
  { pose proof (stk_of_rw_cells bsegs mm _ _ JNK) as SK0. cbn [cells_size csize Nat.add] in SK0.
    eapply stk_merge; [exact STK | replace (bv_unsigned sp + -104) with (SPF + Z.of_nat 424) by lia; exact SK0 | lia]. }
  match goal with |- context [Z_to_bv 64 (?a + 220)] => let v := eval vm_compute in (a + 220) in change (a + 220) with v end.
  let t1 := eval vm_compute in (AZ4_DRET - 12) in let t2 := eval vm_compute in AZ4_DRET in
  destruct HR as [-> | ->]; z4e_to t1 t2;
  [ change (Z_to_bv 64 t1) with (Z_to_bv 64 (AZ4_DRET - 12));
    eapply z4e_dcall; eassumption
  | change (Z_to_bv 64 t2) with (Z_to_bv 64 AZ4_EPI);
    apply z4e_epi; assumption ].
Qed.

  Lemma z4e_join3 : forall mm cs1 cs2 cs3,
    rw_cells bsegs mm SPF cs1 -> cells_size cs1 = 144%nat ->
    rw_cells bsegs mm (SP + -384) cs2 -> cells_size cs2 = 152%nat ->
    rw_cells bsegs mm (SP + -232) cs3 -> cells_size cs3 = 128%nat ->
    exists junk, rw_cells bsegs mm SPF [CB 424 junk].
Proof.
  intros mm cs1 cs2 cs3 H1 S1 H2 S2 H3 S3.
  destruct (rw_cells_forget bsegs mm SPF (cs1 ++ cs2 ++ cs3)) as (j & J).
  - apply rw_cells_app. split; [exact H1|]. rewrite S1.
    replace (SPF + Z.of_nat 144) with (SP + -384) by lia.
    apply rw_cells_app. split; [exact H2|]. rewrite S2.
    replace (SP + -384 + Z.of_nat 152) with (SP + -232) by lia. exact H3.
  - rewrite !cells_size_app, S1, S2, S3 in J. exists j. exact J.
Qed.

  Lemma z4e_mem3 : forall mm, munch DW m0 mm ->
    bytes_at bsegs m0 SS (map (Z_to_bv 8) src) -> bytes_at bsegs m0 (DT + 4) cbs ->
    bytes_at bsegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    bytes_at bsegs mm SS (map (Z_to_bv 8) src) /\ bytes_at bsegs mm (DT + 4) cbs
    /\ bytes_at bsegs mm DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl].
Proof using All.
  intros mm MU SRC1 CBS1 HDR1.
  pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _). pose proof z4e_sp as SPB.
  pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR. unfold KXGoM.apart in DJ3.
  split; [exact (z4e_src mm SRC1 MU) | split].
  - eapply bytes_at_transport; [exact CBS1 | exact MU |]. cbn [disjoint_from]. lia.
  - eapply bytes_at_transport; [exact HDR1 | exact MU |]. cbn [disjoint_from length]. lia.
Qed.

  Lemma z4e_fast_pre :
    0 < DT /\ DT mod 8 = 0 /\ DT + 4 <= lo /\ rng RNG DT 4 /\ rng RNG (shad DT) 1
    /\ 0 <= DST /\ (0 < dcap -> 0 < DST) /\ DST + dcap + 8 <= 2^64
    /\ (0 < n -> SS + n <= lo /\ rng RNG SS n /\ rng RNG (shad SS) (nshad (n + SS mod 8))).
Proof using All.
  pose proof z4e_sp as SPB. pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _).
  pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
  pose proof (AI_block AI _ _ _ _ _ _ _ _ AH HDT) as (_ & _ & DRA & DRS & _).
  pose proof (AI_block_bounds AI _ _ _ _ _ _ AH HDT) as (DB1 & DB2 & DB3). cbn [ab_addr ab_size] in DB1, DB2, DB3.
  pose proof (Z.pow_le_mono_r 2 1 mtl ltac:(lia) ltac:(lia)) as PM. rewrite Z.pow_1_r in PM.
  unfold DTABLE_BYTES, HufHarness.DT_BYTES in *. unfold AIMG_HI in *.
  assert (DSB : 0 <= DST /\ (0 < dcap -> 4096 <= DST) /\ DST + dcap <= 2^47).
  { destruct DSTF as [[-> ->] | (pb & IN)]; [lia|].
    pose proof (AI_block_bounds AI _ _ _ _ _ _ AH IN) as (E1 & E2 & E3). cbn [ab_addr ab_size] in E1, E2, E3.
    unfold AIMG_HI in E1. lia. }
  split; [lia|]. split; [exact (z4_mod16_8 _ B3)|]. split; [lia|].
  split; [eapply rng_sub; [exact DRA | lia | lia]|].
  split.
  { eapply rng_sub; [exact DRS | lia |]. rewrite shlenE.
    pose proof (Z.div_le_lower_bound (4 * (1 + 2 ^ mtl) + 7) 8 1 ltac:(lia) ltac:(lia)). lia. }
  split; [lia|]. split; [lia|]. split; [lia|].
  intros NP. destruct (SRCB NP) as (p & IN & S1 & S2).
  pose proof (AI_block AI _ _ _ _ _ _ _ _ AH IN) as (_ & SAR & SRA & SRS & _).
  pose proof (AI_block_bounds AI _ _ _ _ _ _ AH IN) as (SB1 & SB2 & SB3). cbn [ab_addr ab_size] in SB1, SB2, SB3.
  unfold ablock_range in SAR. destruct SAR as (_ & _ & _ & SAM).
  split; [lia|]. split; [eapply rng_sub; [exact SRA | lia | lia]|].
  eapply rng_sub; [exact SRS | |];
    unfold shad, nshad; rewrite ?shlenE, !Z.shiftr_div_pow2 by lia; change (2^3) with 8;
    Z.div_mod_to_equations; lia.
Qed.

  Lemma z4e_unp4 : forall m, munch DW m0 m ->
    unpoisoned m DT (DT + 4) /\ (0 < n -> unpoisoned m SS (SS + n)).
Proof using All.
  intros m MU. pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _).
  destruct (z4e_unp m MU) as (U1 & U2). split; [|exact U2].
  eapply unpoisoned_sub; [exact U1 | lia | lia].
Qed.

  Ltac z4land :=
    repeat match goal with H : context [Z.land ?a ?c] |- _ =>
      let b := eval vm_compute in (c =? Z.ones 64) in
      lazymatch b with true =>
        replace (Z.land a c) with (a mod 2^64) in H
          by (rewrite <- Z.land_ones by lia; f_equal; vm_compute; reflexivity);
        rewrite (Z.mod_small a) in H by lia
      end end.

  Notation SBW := (Z_to_bv 64 ASHOFF).
  Definition z4f_goal : Prop :=
    forall mm (j0 j1 j2 j3 : list byte)
           (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x21 x22 x24 x25 x26 x27 x28 x29 x30 x31 : word),
    bytes_at bsegs m0 SS (map (Z_to_bv 8) src) -> bytes_at bsegs m0 (DT + 4) cbs ->
    bytes_at bsegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    rw_cells bsegs mm SPF (CB 24 j0 :: Z4F0 DST dcap SS DT src ++ [CB 56 j1; C8 (Z_to_bv 64 (DT + 4)); CB 8 j2]) ->
    fast_args_okA mm (SP + -384) DST dcap SS DT src tl ->
    rw_cells bsegs mm (SP + -232) [CB 128 j3] -> rw_cells bsegs mm (SP + -104) FRS -> stk bsegs mm lo SPF ->
    mem_inv bsegs mm -> munch DW m0 mm -> wmono bsegs m0 mm ->
    evtF bsegs RNG POST (MS (mkR x1 (Z_to_bv 64 SPF) gp tp x5 x6 x7 (Z_to_bv 64 DT) (Z_to_bv 64 n) (Z_to_bv 64 1) x11 x12
                                 x13 x14 x15 x16 x17 (Z_to_bv 64 SS) (Z_to_bv 64 dcap) (Z_to_bv 64 DST) x21 x22 SBW x24 x25
                                 x26 x27 x28 x29 x30 x31)
                            FR (Z_to_bv 64 (AHUF_DX2_4X + 220)) fc None mm (seg_rom bsegs)).

  Definition z4f3_goal : Prop :=
    forall mm (j0 j1 j2 j3 : list byte) (b0 b1 b2 b3 : Z)
           (x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x21 x22 x24 x25 x26 x28 x29 x30 x31 : word),
    tl = 11 -> 10 <= n -> 8 <= jt_len src 0 -> 8 <= jt_len src 2 -> 8 <= jt_len src 4 ->
    jt_len src 0 + jt_len src 2 + jt_len src 4 + 6 + 8 <= n -> 0 < dcap -> 3 * seg < dcap ->
    0 <= b0 < 2^64 -> 0 <= b1 < 2^64 -> 0 <= b2 < 2^64 -> 0 <= b3 < 2^64 ->
    b0 mod 512 <> 0 -> b1 mod 512 <> 0 -> b2 mod 512 <> 0 -> b3 mod 512 <> 0 ->
