  Ltac z4mc_pre :=
    lazymatch goal with MU : munch _ m0 ?m, WM : wmono _ m0 ?m |- _ =>
      let RCm := fresh "RCm" in let ARTm := fresh "ARTm" in let HULLm := fresh "HULLm" in
      pose proof (z4e_rclean m MU WM) as RCm;
      destruct (rclean_shclean _ _ RCm) as (? & HULLm & ? & ?); unfold hull64 in HULLm;
      pose proof (AI_rtcells AI _ _ _ _ _ (z4e_aheap m MU WM)) as ARTm; unfold artcells in ARTm;
      destruct ARTm as (? & ? & ? & ? & ? & ? & ? & ? & ?)
    end.
  Ltac z4mc_close :=
    first [ eassumption | lia | (unfold KHIGH; lia)
          | match goal with H : app_blk _ _ |- app_blk _ _ => eapply app_blk_sub; [exact H | lia | lia | lia] end
          | match goal with H : unpoisoned _ _ _ |- unpoisoned _ _ _ => eapply unpoisoned_sub; [exact H | lia | lia] end
          | lazymatch goal with |- rng _ _ _ => eapply rng_sub; [exact WSK | lia | lia] end
          | reflexivity | (f_equal; lia) ].
  Ltac z4mc dA sA :=
    eapply evtF_cut;
    [ z4mc_pre; eapply AF_fse_rd_mem.amemcpy_specZ with (A := dA) (S := sA) (n := 32) (SPz := SP + -528)
        (RLO1 := r_rlo rstk) (RHI1 := r_rhi rstk) (RLO2 := r_rlo rstk) (RHI2 := r_rhi rstk);
      z4mc_close
    | lazymatch goal with MU : munch _ m0 ?m |- _ => post_call bsegs m end ];
    try (rewrite ret_pc_even; [| lia | reflexivity]).
  Ltac z4recell A NEW :=
    lazymatch goal with H : rw_cells _ ?m A [CB ?k (cells_bytes ?cs)] |- _ =>
      assert (NEW : rw_cells bsegs m A cs)
        by (refine (rw_cells_recell_mid bsegs m A [] [CB k (cells_bytes cs)] [] cs H _ _); [cbn; tauto | reflexivity]);
      clear H end.
  Ltac z4cut A k n NEWL NEWR :=
    lazymatch goal with H : rw_cells _ ?m A [CB _ _] |- _ =>
      let H' := fresh "H" in
      pose proof (rw_cells_cb_split bsegs _ _ _ _ k n H eq_refl eq_refl) as H'; clear H;
      cbv [cb_split cb_pieces] in H'; cbn in H';
      apply (proj1 (rw_cells_app bsegs _ _ [CB _ _] _)) in H';
      destruct H' as (NEWL & NEWR); cbn [cells_size csize Nat.add] in NEWR
    end.

  Lemma z4f_a : z4f3_goal -> z4f_goal.
Proof using All.
  intros F300. unfold z4f_goal.
  intros mm j0 j1 j2 j3 x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x21 x22 x24 x25 x26 x27 x28 x29 x30 x31
    SRC1 CBS1 HDR1 FR0 FAOK FL FRB ST MI MU WM.
  pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
  pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _). unfold AIMG_HI in B1.
  pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
  pose proof z4e_fast_pre as (FP1 & FP2 & FP3 & FP4 & FP5 & FP6 & FP7 & FP8 & FPS).
  pose proof (AI_rtcells AI _ _ _ _ _ (z4e_aheap mm MU WM)) as (_ & GOT & _ & _ & SHB & _).
  unfold HUF_DEC_STACK_A in LOS.
  destruct FAOK as (TL11 & N10 & JL1 & JL2 & JL3 & JLS & DCP & SG3 & b0 & b1 & b2 & b3 & BB0 & BB1 & BB2 & BB3
                    & BM0 & BM1 & BM2 & BM3 & ARG).
  unfold Z4F0 in FR0. cbn [app] in FR0.
  unfold fast_args_cells in ARG. cbv zeta in ARG.
  match goal with |- context [Z_to_bv 64 (?a + 220)] => let v := eval vm_compute in (a + 220) in change (a + 220) with v end.
  do 2 zstep.
  zstep. if_cases K228; zify_cond K228; [| exfalso; lia].
  do 6 zstep.
  apply (proj1 (rw_cells_app bsegs _ _ [C8 _; C8 _; C8 _; C8 _] _)) in ARG.
  destruct ARG as (AR0 & ARG). cbn [cells_size csize Nat.add] in ARG.
  replace (SP + -384 + Z.of_nat 32) with (SP + -352) in ARG by lia.
  apply (proj1 (rw_cells_app bsegs _ _ [C8 _; C8 _; C8 _; C8 _] _)) in ARG.
  destruct ARG as (AR1 & ARG). cbn [cells_size csize Nat.add] in ARG.
  replace (SP + -352 + Z.of_nat 32) with (SP + -320) in ARG by lia.
  apply (proj1 (rw_cells_app bsegs _ _ [C8 _; C8 _; C8 _; C8 _] _)) in ARG.
  destruct ARG as (AR2 & AR3). cbn [cells_size csize Nat.add] in AR3.
  replace (SP + -320 + Z.of_nat 32) with (SP + -288) in AR3 by lia.
  pose proof (proj2 (proj1 AR2)) as SBb.
  z4cut (SP + -232) 96%nat 32%nat LC1 LC2.
  replace (SP + -232 + Z.of_nat 96) with (SP + -136) in LC2 by lia.
  zstep.
  z4mc (SP + -136) (SP + -320).
  z4recell (SP + -136) LCb.
  do 3 zstep.
  pose proof (proj2 (proj1 AR0)) as SBi.
  z4cut (SP + -232) 64%nat 32%nat LC1' LC3.
  replace (SP + -232 + Z.of_nat 64) with (SP + -168) in LC3 by lia.
  zstep.
  z4mc (SP + -168) (SP + -384).
  z4recell (SP + -168) LCi.
  do 4 zstep.
  pose proof (proj2 (proj1 AR1)) as SBo.
  z4cut (SP + -232) 32%nat 32%nat LC1'' LC4.
  replace (SP + -232 + Z.of_nat 32) with (SP + -200) in LC4 by lia.
  zstep.
  z4mc (SP + -200) (SP + -352).
  z4recell (SP + -200) LCo.
  let v := eval vm_compute in (AHUF_DX2_4X + 300) in change (Z_to_bv 64 v) with (Z_to_bv 64 (AHUF_DX2_4X + 300)).
  eapply (F300 _ _ _ _ _ b0 b1 b2 b3); eassumption.
Qed.

