  Lemma z4f_b1 : z4f4_goal -> z4f3_goal.
  Proof using All.
    intros F460. unfold z4f3_goal.
    intros mm j0 j1 j2 j3 b0 b1 b2 b3 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x21 x22 x24 x25 x26 x28 x29 x30 x31
      TL11 N10 JL1 JL2 JL3 JLS DCP SG3 BB0 BB1 BB2 BB3 BM0 BM1 BM2 BM3 SRC1 CBS1 HDR1
      FR0 AR0 AR1 AR2 AR3 LC1 LCo LCi LCb FL ST MI MU WM.
    pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
    pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _). unfold AIMG_HI in B1.
    pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
    pose proof z4e_fast_pre as (FP1 & FP2 & FP3 & FP4 & FP5 & FP6 & FP7 & FP8 & FPS).
    unfold HUF_DEC_STACK_A in LOS.
    let v := eval vm_compute in (AHUF_DX2_4X + 300) in change (AHUF_DX2_4X + 300) with v.
    zstep.
    zstep. if_cases K304; zify_cond K304; [| exfalso; z4land; lia].
    do 4 zstep.
    zstep. if_cases K328; zify_cond K328; [| exfalso; z4land; lia].
    do 3 zstep.
    zstep. if_cases K348; zify_cond K348; [| exfalso; z4land; lia].
    do 5 zstep.
    zstep. if_cases K376; zify_cond K376; [| exfalso; z4land; lia].
    do 3 zstep.
    zstep. if_cases K396; zify_cond K396; [| exfalso; match type of K396 with context [Z.ltb ?a ?b] => rewrite (proj2 (Z.ltb_lt a b)) in K396 by lia end; apply K396; reflexivity].
    do 5 zstep.
    zstep. if_cases K424; zify_cond K424; [| exfalso; z4land; lia].
    do 5 zstep.
    zstep. if_cases K452; zify_cond K452; [| exfalso; z4land; lia].
    let v := eval vm_compute in (AHUF_DX2_4X + 300) in change (Z_to_bv 64 v) with (Z_to_bv 64 (AHUF_DX2_4X + 300)).
    let v := eval vm_compute in (AHUF_DX2_4X + 460) in change (Z_to_bv 64 v) with (Z_to_bv 64 (AHUF_DX2_4X + 460)).
