  Qed.
  Notation HD4 := [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl].

  Lemma z4e_x2ok : huf_x2_ok (HD4 ++ cbs) tl /\ huf_nb_ok true (HD4 ++ cbs) tl.
  Proof using All.
    destruct TOK as (TL1 & LEN & OK). unfold FseNCount.Zlength in LEN.
    split; intros i Hi; destruct (OK i Hi) as (Q1 & Q2 & Q3); rewrite ECB.
    - exists (Z_to_bv 8 (x2_len (nth (Z.to_nat i) cells x2_default))). split; [|rewrite byte_lit; lia].
      rewrite nth_error_app2 by (cbn [length]; lia). cbn [length].
      replace (Z.to_nat (4 * i + 7) - 4)%nat with (4 * Z.to_nat i + 3)%nat by lia.
      rewrite z4f_nth_firstn by (pose proof (Z.pow_pos_nonneg 2 tl ltac:(lia) ltac:(lia)); lia).
      rewrite x2_bytes'_nth by lia. reflexivity.
    - exists (Z_to_bv 8 (x2_nbBits (nth (Z.to_nat i) cells x2_default))). split; [|rewrite byte_lit; lia].
      rewrite nth_error_app2 by (cbn [length]; lia). cbn [length].
      replace (Z.to_nat (4 * i + 6) - 4)%nat with (4 * Z.to_nat i + 2)%nat by lia.
      rewrite z4f_nth_firstn by (pose proof (Z.pow_pos_nonneg 2 tl ltac:(lia) ltac:(lia)); lia).
      rewrite x2_bytes'_nth by lia. reflexivity.
  Qed.

  Lemma z4e_shsp : forall A k, A mod 8 = 0 -> 0 <= k -> shspan A k = shlen (k + 7).
  Proof.
    intros A k HA Hk. unfold shspan, shlen. rewrite Z.shiftr_div_pow2 by lia. change (2 ^ 3) with 8.
    pose proof (Z.div_mod A 8 ltac:(lia)) as E. rewrite HA in E.
    replace (A + k + 7) with ((k + 7) + (A / 8) * 8) by lia. rewrite Z.div_add by lia. lia.
  Qed.

  Lemma z4e_shsp2 : forall A k, shspan A k = nshad (k + A mod 8).
  Proof.
    intros A k. unfold shspan. rewrite nshad_div. pose proof (Z.div_mod A 8 ltac:(lia)) as E.
    replace (A + k + 7) with ((k + A mod 8 + 7) + (A / 8) * 8) by lia. rewrite Z.div_add by lia. lia.
  Qed.

  Lemma z4e_azs : forall m, munch DW m0 m -> wmono bsegs m0 m ->
    exists RLO RHI, shclean m lo SP RLO RHI /\ rng RNG (shad RLO) (shad RHI - shad RLO).
  Proof using All.
    intros m MU WM. pose proof z4e_sp as SPB. exists (r_rlo rstk), (r_rhi rstk). split; [|exact RRS].
    eapply shclean_sub; [exact (rclean_shclean _ _ (z4e_rclean m MU WM)) | exact RLO | lia | exact RHI].
  Qed.

  Lemma z4e_x42actx : forall m, munch DW m0 m -> wmono bsegs m0 m -> 0 < n ->
    x42e_actx RNG m SP DST dcap SS n DT (4 + zlen cbs) lo.
  Proof using All.
    intros m MU WM NP.
    assert (UDST : 0 < dcap -> unpoisoned m DST (DST + dcap)).
    { intros DCP. destruct DSTF as [[D0 C0] | (pb & IN)]; [lia|]. z4e_sb z4s_blk_unp. }
    pose proof z4e_sp as SPB. pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _).
    pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
    pose proof z4e_fast_pre as (FP1 & FP2 & FP3 & FP4 & FP5 & FP6 & FP7 & FP8 & FPS).
    pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
    pose proof (AI_block AI _ _ _ _ _ _ _ _ AH HDT) as (_ & (_ & _ & _ & DTM) & DRA & DRS & _).
    destruct (FPS NP) as (FS1 & FS2 & FS3).
    destruct (z4e_unp m MU) as (U1 & U2).
    unfold HUF_DEC_STACK_A in LOS. unfold DTABLE_BYTES, HufHarness.DT_BYTES in *.
    unfold x42e_actx.
    split; [exact (U2 NP)|]. split; [eapply unpoisoned_sub; [exact U1 | lia | lia]|].
    split; [exact UDST|].
    split; [exact FS2|]. split; [rewrite z4e_shsp2; exact FS3|].
    split; [eapply rng_sub; [exact DRA | lia | lia]|].
    split; [rewrite z4e_shsp by lia; eapply rng_sub; [exact DRS | lia |];
            unfold shlen; rewrite !Z.shiftr_div_pow2 by lia; apply Z.add_le_mono_l, Z.div_le_mono; lia|].
    split; [intros DCP; destruct DSTF as [[-> ->] | (pb & IN)]; [lia|];
            pose proof (AI_block AI _ _ _ _ _ _ _ _ AH IN) as (_ & _ & XRA & _); exact XRA|].
    split; [intros DCP; destruct DSTF as [[-> ->] | (pb & IN)]; [lia|];
            pose proof (AI_block AI _ _ _ _ _ _ _ _ AH IN) as (_ & (_ & _ & _ & XM) & _ & XRS & _);
            rewrite z4e_shsp by lia; exact XRS|].
    split; [eapply rng_sub; [exact WSK | lia | lia]|].
    split; [exact WIM|].
    exact (AI_rtcells AI _ _ _ _ _ (z4e_aheap m MU WM)).
  Qed.

  Lemma z4e_x42ctx : 0 < dcap -> 0 < n ->
    x42e_ctx SP DST dcap SS n DT (4 + zlen cbs) tl lo (map (Z_to_bv 8) src) (HD4 ++ cbs).
  Proof using All.
    intros DCP NP.
    pose proof z4e_d0 as (D0 & D1 & D2). pose proof z4e_sp as SPB.
    pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
    pose proof z4e_fast_pre as (FP1 & FP2 & FP3 & FP4 & FP5 & FP6 & FP7 & FP8 & FPS).
    pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
    pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _).
    assert (DSA : AIMG_HI <= DST).
    { destruct DSTF as [[D3 C0] | (pb & IN)]; [lia|].
      pose proof (AI_block_bounds AI _ _ _ _ _ _ AH IN) as (E1 & _). exact E1. }
    assert (SSA : AIMG_HI <= SS).
    { destruct (SRCB NP) as (p & IN & S1 & S2).
      pose proof (AI_block_bounds AI _ _ _ _ _ _ AH IN) as (E1 & _). cbn [ab_addr] in E1. lia. }
    pose proof TOK as (TL1 & _).
    unfold x42e_ctx. unfold HUF_DEC_STACK_A in LOS. unfold AIMG_HI in *.
    repeat match goal with |- _ /\ _ => split end;
