    lazymatch type of E with Z.lxor _ ?c = _ =>
      assert (HC : K = c) by (rewrite HK; reflexivity); rewrite HC, E end.
    apply bv_eq. rewrite !unsigned_lit_wrap. lia.
  Qed.

