  Lemma z4e_mkz4m : forall m5 mm (w0 w1 w2 w9 w10 w11 w12 w13 w14 w15 w17 : word) (ws lc : list word),
    munch DW m0 m5 -> wmono bsegs m0 m5 ->
    AF_huf_z4f_ffo.X42PF ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 SP lo mm ->
    munch [(DST, DST + dcap); (SP - 3136, SP)] m5 mm -> wmono bsegs m5 mm -> mem_inv bsegs mm ->
    bytes_at bsegs mm DT (HD4 ++ cbs) -> bytes_at bsegs mm SS (map (Z_to_bv 8) src) ->
    rw_cells bsegs mm SPF [C8 w0; C8 w1; C8 w2; C8 (Z_to_bv 64 SS); C8 (Z_to_bv 64 n); C8 (Z_to_bv 64 DT);
                           C8 (Z_to_bv 64 DST); C8 (Z_to_bv 64 dcap); C8 (Z_to_bv 64 (DST + dcap));
                           C8 w9; C8 w10; C8 w11; C8 w12; C8 w13; C8 w14; C8 w15; C8 (Z_to_bv 64 (DT + 4)); C8 w17] ->
    rw_cells bsegs mm (SP + -384) (map C8 ws) -> length ws = 19%nat ->
    rw_cells bsegs mm (SP + -232) (map C8 lc) -> length lc = 16%nat ->
    0 < dcap ->
    AF_huf_z4m.Z4M ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm w17 ws.
  Proof using All.
    intros m5 mm w0 w1 w2 w9 w10 w11 w12 w13 w14 w15 w17 ws lc MU5 WM5 PV MU WM MI DTB SRCM FM AR LAR LC LLC DCP.
    pose proof z4e_sp as SPB. unfold HUF_DEC_STACK_A in LOS.
    unfold AF_huf_z4f_ffo.X42PF in PV. destruct PV as (FQ & STK).
    assert (MU0 : munch DW m0 mm).
    { eapply munch_trans; [exact MU5|]. eapply munch_weaken; [| exact MU].
      unfold sub_fp. cbn [outside fst snd app]. intros; lia. }
    assert (WM0 : wmono bsegs m0 mm) by (eapply wmono_trans; eassumption).
    apply (proj1 (rw_cells_app bsegs _ _ [C8 _; C8 _; C8 _] _)) in FM. destruct FM as (FA & FM).
    cbn [cells_size csize Nat.add] in FM. replace (SPF + Z.of_nat 24) with (SPF + 24) in FM by lia.
    apply (proj1 (rw_cells_app bsegs _ _ [C8 _; C8 _; C8 _; C8 _; C8 _; C8 _] _)) in FM. destruct FM as (FB & FM).
    cbn [cells_size csize Nat.add] in FM. replace (SPF + 24 + Z.of_nat 48) with (SPF + 72) in FM by lia.
    apply (proj1 (rw_cells_app bsegs _ _ [C8 _; C8 _; C8 _; C8 _; C8 _; C8 _; C8 _] _)) in FM. destruct FM as (FC & FD).
    cbn [cells_size csize Nat.add] in FD. replace (SPF + 72 + Z.of_nat 56) with (SPF + 128) in FD by lia.
    unfold AF_huf_z4m.Z4M.
    split; [destruct (z4e_out mm WM0) as [[D0 C0] | X]; [lia | exact X]|].
    split; [exact SRCM|].
    split; [apply bytes_at_app in DTB; destruct DTB as (_ & DTB'); cbn [length Z.of_nat] in DTB'; exact DTB'|].
    split; [eapply z4_stk_ext; [exact STK | exact FA | lia | cbn [cells_size csize Nat.add]; lia]|].
    split; [exact FB|].
    split; [pose proof (stk_of_rw_cells bsegs mm _ _ FC) as S; cbn [cells_size csize Nat.add] in S;
            replace (SPF + 72 + Z.of_nat 56) with (SPF + 128) in S by lia; exact S|].
    split; [exact FD|].
    split; [replace (SPF + 144) with (SP + -384) by lia; exact (z4_u64arr_of_C8 _ _ _ AR)|].
    split; [exact LAR|].
    split; [pose proof (stk_of_rw_cells bsegs mm _ _ LC) as S; rewrite z4_cells_size_C8, LLC in S;
            replace (SP + -232 + Z.of_nat (8 * 16)) with (SP + -104) in S by lia;
            replace (SPF + 296) with (SP + -232) by lia; exact S|].
    split; [exact FQ|].
    split; [exact MI|]. split; [exact MU0 | exact WM0].
  Qed.

