  Lemma z4e_f3z : tl = 11 -> 10 <= n -> 3 * seg < dcap -> 0 < dcap -> z4f_f3.
  Proof using All.
    intros T11 N10 SG3 DCP m5 MU5 WM5. unfold AF_huf_z4f_ffo.x42e_f3_stmt.
    intros mm l1 l2 l3 i0 i1 i2 i3 o0 o1 o2 o3 e0 e1 e2 e3 c0 c1 c2 c3
      x5 x6 x7 x8 x9 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x24 x25 x27 x28 x29 x30 x31
      w0 w1 w2 w9 w10 w11 w12 w13 w14 w15
      PV MU WM MI OUT DTB FRS ARGS LOC SRCM HD HL1 HL2 HL3 HLN
      HI0 HN0 HO0 HB0 HI1 HN1 HO1 HB1 HI2 HN2 HO2 HB2 HI3 HN3 HO3 HB3.
    pose proof z4e_sp as SPB. pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _).
    pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
    pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
    destruct DSTF as [[D0 C0] | (pb & HDB)]; [lia|].
    destruct (SRCB ltac:(lia)) as (psb & INS & SB1 & SB2).
    pose proof (AI_block AI _ _ _ _ _ _ _ _ AH HDT) as (_ & _ & WDT & WDTS & _).
    pose proof (AI_block AI _ _ _ _ _ _ _ _ AH HDB) as (_ & _ & WDB & WDBS & _).
    pose proof (AI_block AI _ _ _ _ _ _ _ _ AH INS) as (_ & (SA1 & _ & _ & SA4) & WSB & WSBS & _).
    replace (SBL + (SBH - SBL)) with SBH in SA1 by lia.
    destruct (z4e_unp m0 (munch_refl _ _)) as (UDT & _).
    assert (UDB : unpoisoned m0 DST (DST + dcap)) by z4e_sbr z4s_blk_unp.
    assert (USB : unpoisoned m0 SBL SBH) by z4e_sbr z4s_unpS.
    pose proof TLM as TLM1. pose proof TOK as TOK1. pose proof ECB as ECB1. pose proof LCB as LCB1.
    rewrite T11 in TLM1, TOK1, ECB1, LCB1.
    repeat match goal with H : context [tl] |- _ =>
      tryif (first [constr_eq H TLM | constr_eq H TOK | constr_eq H ECB | constr_eq H LCB | constr_eq H T11])
      then fail else rewrite T11 in H end.
    rewrite ?T11.
    set (ws := [Z_to_bv 64 (SS + i0); Z_to_bv 64 (SS + i1); Z_to_bv 64 (SS + i2); Z_to_bv 64 (SS + i3);
                Z_to_bv 64 (DST + o0); Z_to_bv 64 (DST + o1); Z_to_bv 64 (DST + o2); Z_to_bv 64 (DST + o3);
                c0; c1; c2; c3; Z_to_bv 64 (DT + 4); Z_to_bv 64 SS; Z_to_bv 64 (DST + dcap); Z_to_bv 64 (SS + 6);
                Z_to_bv 64 (SS + 6 + l1); Z_to_bv 64 (SS + 6 + l1 + l2); Z_to_bv 64 (SS + 6 + l1 + l2 + l3)]).
    eapply (AF_huf_z4fin4.z4f_fin AI L RNG st LB ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc m0
              DST dcap SS DT mtl lo src cbs pdt pb SBL SBH cells) with (ws := ws).
    all: first [ eassumption | (rewrite T11; eassumption) | lia | (split; lia) | (split; [exact SA1 | lia]) | reflexivity
               | (unfold KXGoM.apart in *; lia) | idtac ].
    - eapply (z4e_mkz4m m5 mm w0 w1 w2 w9 w10 w11 w12 w13 w14 w15 _ ws
                [e0; e1; e2; e3; Z_to_bv 64 (DST + o0); Z_to_bv 64 (DST + o1); Z_to_bv 64 (DST + o2);
                 Z_to_bv 64 (DST + o3); Z_to_bv 64 (SS + i0); Z_to_bv 64 (SS + i1); Z_to_bv 64 (SS + i2);
                 Z_to_bv 64 (SS + i3); c0; c1; c2; c3]);
        first [eassumption | (rewrite T11; eassumption) | reflexivity | lia | (unfold ws; cbn [map]; exact ARGS) | (cbn [map]; exact LOC)].
    - pose proof z4e_fast_pre as (FP1 & FP2 & FP3 & FP4 & FP5 & FP6 & FP7 & FP8 & FPS).
      destruct (FPS ltac:(lia)) as (FS1 & _ & _).
      intros i Hi. unfold ws.
      assert (HC : i = 0 \/ i = 1 \/ i = 2 \/ i = 3) by lia.
      destruct HC as [-> | [-> | [-> | ->]]]; cbn.
      + exists (SS + i0), (DST + o0), (bv_unsigned c0), (SS + 6).
        rewrite Z_to_bv_bv_unsigned. pose proof (bv_unsigned_in_range _ c0). unfold bv_modulus in *.
        repeat split; first [reflexivity | lia].
      + exists (SS + i1), (DST + o1), (bv_unsigned c1), (SS + 6 + l1).
        rewrite Z_to_bv_bv_unsigned. pose proof (bv_unsigned_in_range _ c1). unfold bv_modulus in *.
        repeat split; first [reflexivity | lia].
      + exists (SS + i2), (DST + o2), (bv_unsigned c2), (SS + 6 + l1 + l2).
        rewrite Z_to_bv_bv_unsigned. pose proof (bv_unsigned_in_range _ c2). unfold bv_modulus in *.
        repeat split; first [reflexivity | lia].
      + exists (SS + i3), (DST + o3), (bv_unsigned c3), (SS + 6 + l1 + l2 + l3).
        rewrite Z_to_bv_bv_unsigned. pose proof (bv_unsigned_in_range _ c3). unfold bv_modulus in *.
        repeat split; first [reflexivity | lia].
  Qed.

  Ltac z4join H1 H2 NEW :=
    lazymatch type of H1 with rw_cells _ ?m ?A ?cs1 => lazymatch type of H2 with rw_cells _ _ ?B ?cs2 =>
      assert (NEW : rw_cells bsegs m A (cs1 ++ cs2))
        by (apply (proj2 (rw_cells_app bsegs m A cs1 cs2)); split; [exact H1|];
            replace (A + Z.of_nat (cells_size cs1)) with B by (cbn [cells_size csize Nat.add]; lia); exact H2);
      clear H1 H2; cbn [app] in NEW
    end end.

  Lemma z4e_lb8 : forall z, 0 <= z -> z mod 512 <> 0 -> AF_huf_z4f_defs.LB 8 z.
  Proof.
    intros z Hz Hm. change 512 with (2^9) in Hm.
    pose proof (Z.mod_pos_bound z (2^9) ltac:(lia)) as Hb.
    assert (Hp : 0 < z mod 2^9) by lia.
    pose proof (proj1 (Z.log2_lt_pow2 (z mod 2^9) 9 Hp) ltac:(lia)) as L9.
    pose proof (Z.log2_nonneg (z mod 2^9)) as L0.
    exists (Z.log2 (z mod 2^9)). split; [lia|].
    rewrite <- (Z.mod_pow2_bits_low z 9) by lia. apply Z.bit_log2. exact Hp.
  Qed.

  Lemma z4f_b2 : z4f4_goal.
  Proof using All.
    unfold z4f4_goal.
    intros mm j0 j1 j2 b0 b1 b2 b3 x5 x6 x7 x13 x14 x15 x16 x17 x21 x22 x24 x25 x26 x28 x29 x30 x31
      TL11 N10 JL1 JL2 JL3 JLS DCP SG3 BB0 BB1 BB2 BB3 BM0 BM1 BM2 BM3 SRC1 CBS1 HDR1
      FR0 AR0 AR1 AR2 AR3 LC1 LCo LCi LCb FL ST MI MU WM.
    pose proof (z4e_f3z TL11 N10 SG3 DCP) as F3Z.
    pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
    pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _). unfold AIMG_HI in B1.
    pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
    unfold HUF_DEC_STACK_A in LOS.
    let v := eval vm_compute in (AHUF_DX2_4X + 460) in change (AHUF_DX2_4X + 460) with v.
    let v := eval vm_compute in (AHUF_DX2_4X + 300) in change (AHUF_DX2_4X + 300) with v.
    do 25 zstep.
    c8ifyF FR0. c8ifyF FR0. absj FR0.
    z4join LCi LCb L1. z4join LCo L1 L2. z4join LC1 L2 LOCH.
    z4join AR2 AR3 A1. z4join AR1 A1 A2. z4join AR0 A2 ARGH.
    erewrite z4e_ndq; [| reflexivity | lia].
    destruct (z4e_mem3 m1 MU SRC1 CBS1 HDR1) as (SRC2 & CBS2 & HDR2).
    pose proof (proj2 (bytes_at_app bsegs m1 DT _ _) (conj HDR2 CBS2)) as DTB2. cbn [length Z.of_nat] in DTB2.
    pose proof (z4e_outstk m1 MU WM DCP) as OUT.
    pose proof (z4e_x42ctx DCP ltac:(lia)) as CTX5.
    pose proof (z4e_x42actx m1 MU WM ltac:(lia)) as ACTX5.
    pose proof (z4e_azs m1 MU WM) as AZS5.
    assert (EI0 : SS + 6 + jt_len src 0 - 8 = SS + (6 + jt_len src 0 - 8)) by lia.
    assert (EI1 : SS + 6 + jt_len src 0 + jt_len src 2 - 8 = SS + (6 + jt_len src 0 + jt_len src 2 - 8)) by lia.
    assert (EI2 : SS + 6 + jt_len src 0 + jt_len src 2 + jt_len src 4 - 8
                  = SS + (6 + jt_len src 0 + jt_len src 2 + jt_len src 4 - 8)) by lia.
    assert (EI3 : SS + n - 8 = SS + (n - 8)) by lia.
    rewrite EI0, EI1, EI2, EI3 in LOCH |- *.
    assert (EO : Z_to_bv 64 DST = Z_to_bv 64 (DST + 0)) by (f_equal; lia). rewrite EO in LOCH |- *.
    replace (Z_to_bv 64 (-16)) with (Z_to_bv 64 (2^64 - 16)) by (apply bv_eq; vm_compute; reflexivity).
    destruct z4e_x2ok as (X2 & NB).
    eapply AF_huf_z4f_ffo.x42e_fo with (RNG := RNG) (ra := ra) (gp := gp) (tp := tp)
      (s0 := s0) (s1 := s1) (s2 := s2) (s3 := s3) (s4 := s4) (s5 := s5) (s6 := s6) (s7 := s7) (s8 := s8) (s9 := s9)
      (s10 := s10) (s11 := s11) (F := FR) (fc := fc) (m0 := m1) (SPV := SP) (DST := DST) (dcap := dcap) (SRC := SS)
      (n := n) (DT := DT) (DTB := 4 + zlen cbs) (tl := tl) (lo := lo) (src := map (Z_to_bv 8) src) (dtb := HD4 ++ cbs)
      (POST := POST) (CTX := CTX5) (X2OK := X2) (NBOK := NB) (ACTX := ACTX5) (TL11 := TL11)
      (MC := AF_fse_rd_mem.amemcpy_specZ) (AZS := AZS5) (F3 := F3Z m1 MU WM)
      (q := seg) (l1 := jt_len src 0) (l2 := jt_len src 2) (l3 := jt_len src 4)
      (i0 := 6 + jt_len src 0 - 8) (i1 := 6 + jt_len src 0 + jt_len src 2 - 8)
      (i2 := 6 + jt_len src 0 + jt_len src 2 + jt_len src 4 - 8) (i3 := n - 8)
      (o0 := 0) (o1 := seg) (o2 := 2 * seg) (o3 := 3 * seg) (k := Z.to_nat (dcap - 3 * seg + 1)).
    all: first [ exact (conj FL ST) | apply munch_refl | apply wmono_refl | eassumption | reflexivity
               | (apply lbw_Z; [lia | apply z4e_lb8; lia]) | (rewrite Z2Nat.id by lia; lia) | lia ].
  Qed.

