  Lemma z4e_fa : forall mm (j0 j1 j2 ja j3 : list byte)
      (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6 : word),
    a0 = Z_to_bv 64 (SP + -384) -> a1 = Z_to_bv 64 DST -> a2 = Z_to_bv 64 dcap -> a3 = Z_to_bv 64 SS ->
    a4 = Z_to_bv 64 n -> a5 = Z_to_bv 64 DT -> x23 = SBW ->
    bytes_at bsegs m0 SS (map (Z_to_bv 8) src) -> bytes_at bsegs m0 (DT + 4) cbs ->
    bytes_at bsegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    rw_cells bsegs mm SPF (CB 24 j0 :: Z4F0 DST dcap SS DT src ++ [CB 56 j1; C8 (Z_to_bv 64 (DT + 4)); CB 8 j2]) ->
    rw_cells bsegs mm (SP + -384) [CB 152 ja] -> rw_cells bsegs mm (SP + -232) [CB 128 j3] ->
    rw_cells bsegs mm (SP + -104) FRS -> stk bsegs mm lo SPF ->
    mem_inv bsegs mm -> munch DW m0 mm -> wmono bsegs m0 mm ->
    evtF bsegs RNG POST (MS (mkR (Z_to_bv 64 (AHUF_DX2_4X + 220)) (Z_to_bv 64 SPF) gp tp t0 t1 t2 (Z_to_bv 64 DT)
                                 (Z_to_bv 64 n) a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 SS) (Z_to_bv 64 dcap) (Z_to_bv 64 DST)
                                 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6)
                            FR (Z_to_bv 64 AHUF_FAST_ARGS_INIT) fc None mm (seg_rom bsegs)).
Proof using All.
  intros mm j0 j1 j2 ja j3 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 x21 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6
    E0 E1 E2 E3 E4 E5 E6 SRC0 CBS0 HDR0 F1 F2 F3 FF ST MI MU WM.
  subst x23.
  pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
  pose proof z4e_fast_pre as (FP1 & FP2 & FP3 & FP4 & FP5 & FP6 & FP7 & FP8 & FPS).
  pose proof (proj1 TOK) as TLB.
  unfold HUF_DEC_STACK_A in LOS.
  assert (USP : bv_unsigned (Z_to_bv 64 SPF) = SPF) by (apply unsigned_lit; lia).
  destruct (z4e_mem3 mm MU SRC0 CBS0 HDR0) as (SRC1 & CBS1 & HDR1).
  pose proof (z4e_aheap mm MU WM) as AHm.
  destruct (z4e_unp4 mm MU) as (UD & US).
  pose proof (z4e_rclean mm MU WM) as RCm.
  eapply evtF_cut.
  { eapply (FAP RNG) with (A := SP + -384) (DST := DST) (dcap := dcap) (S := SS) (DT := DT)
      (mtl := mtl) (tt := 1) (tl := tl) (mtl' := mtl) (src := src) (lo := lo) (rstk := rstk);
      rewrite ?USP;
      first [ eassumption | exact (AI_rtcells AI _ _ _ _ _ AHm)
            | (intro; destruct (FPS ltac:(lia)) as (? & ? & ?); first [lia | split; assumption])
            | (unfold AHUF_FAST_ARGS_STACK; eapply rng_sub; [exact WSK | lia | lia])
            | (unfold AHUF_FAST_ARGS_STACK; lia) | (Z.div_mod_to_equations; lia) | lia ]. }
  cbv beta. intros ms' P. unfold fast_args_postA in P.
  destruct P as (u0 & u1 & u2 & b1 & b2 & b3 & b4 & b5 & b6 & b7 & u3 & u4 & u5 & u6 & r & m' & -> & MU2 & WM2 & MI2
                 & ST2 & (ja' & JA') & RC).
  rewrite USP in MU2, ST2. unfold AHUF_FAST_ARGS_STACK in MU2.
  rewrite (ret_pc_even (AHUF_DX2_4X + 220)); [| unfold AHUF_DX2_4X; lia | reflexivity].
  pose proof (rw_cells_transport _ _ _ _ _ _ F1 MU2 WM2) as F1'.
  specialize (F1' ltac:(cbn [disjoint_from cells_size csize Nat.add Z4F0 app]; repeat split; lia)).
  pose proof (rw_cells_transport _ _ _ _ _ _ F3 MU2 WM2) as F3'.
  specialize (F3' ltac:(cbn [disjoint_from cells_size csize Nat.add]; repeat split; lia)).
  pose proof (rw_cells_transport _ _ _ _ _ _ FF MU2 WM2) as FF'.
  specialize (FF' ltac:(cbn [disjoint_from cells_size csize Nat.add]; repeat split; lia)).
  assert (MU3 : munch DW m0 m').
  { eapply munch_trans; [exact MU |]. eapply munch_weaken; [| exact MU2]. intros x X. cbn [outside] in X |- *.
    destruct X as (X1 & X2 & _). split; [lia | split; [lia | exact I]]. }
  assert (WM3 : wmono bsegs m0 m') by (eapply wmono_trans; [exact WM | exact WM2]).
  destruct (z4e_mem3 m' MU3 SRC0 CBS0 HDR0) as (SRC2 & CBS2 & HDR2).
  destruct RC as [-> | [-> | (-> & OK)]].
  - destruct (z4e_join3 m' _ _ _ F1' eq_refl JA' eq_refl F3' eq_refl) as (jk & JK).
    eapply z4e_nofast; [left; reflexivity | eassumption ..].
  - destruct (z4e_join3 m' _ _ _ F1' eq_refl JA' eq_refl F3' eq_refl) as (jk & JK).
    eapply z4e_nofast; [right; reflexivity | eassumption ..].
  - pose proof z4f_full as FG. unfold z4f_goal in FG. eapply FG; eassumption.
Qed.

  (* [comment removed for export] *)
  Definition FAW (b0 b1 b2 b3 : Z) : list word :=
    let l1 := jt_len src 0 in let l2 := jt_len src 2 in let l3 := jt_len src 4 in
    [ Z_to_bv 64 (SS + 6 + l1 - 8); Z_to_bv 64 (SS + 6 + l1 + l2 - 8); Z_to_bv 64 (SS + 6 + l1 + l2 + l3 - 8);
      Z_to_bv 64 (SS + n - 8);
      Z_to_bv 64 DST; Z_to_bv 64 (DST + seg); Z_to_bv 64 (DST + 2 * seg); Z_to_bv 64 (DST + 3 * seg);
      Z_to_bv 64 b0; Z_to_bv 64 b1; Z_to_bv 64 b2; Z_to_bv 64 b3;
      Z_to_bv 64 (DT + 4); Z_to_bv 64 SS; Z_to_bv 64 (DST + dcap);
      Z_to_bv 64 (SS + 6); Z_to_bv 64 (SS + 6 + l1); Z_to_bv 64 (SS + 6 + l1 + l2); Z_to_bv 64 (SS + 6 + l1 + l2 + l3) ].

  (* [comment removed for export] *)
  Ltac z4wsrd A i :=
    lazymatch goal with W : u64arr bsegs ?mm A ?ws |- evtF _ _ _ (MS _ _ _ _ _ ?mm _) =>
      pose proof (u64arr_read bsegs mm A ws i _ _ W eq_refl ltac:(lia) ltac:(unfold wa; f_equal; lia)) end.

  (* [comment removed for export] *)
  Lemma z4_entry : forall (t0 t1 t2 a6 a7 t3 t4 t5 t6 : word) (flags : Z),
    bytes_at bsegs m0 SS (map (Z_to_bv 8) src) -> bytes_at bsegs m0 (DT + 4) cbs ->
    bytes_at bsegs m0 DT [Z_to_bv 8 mtl; Z_to_bv 8 1; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
    stk bsegs m0 lo SP -> mem_inv bsegs m0 -> 0 <= flags < 64 ->
    evtF bsegs RNG POST (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 DST) (Z_to_bv 64 dcap) (Z_to_bv 64 SS) (Z_to_bv 64 n)
                                 (Z_to_bv 64 DT) (Z_to_bv 64 flags) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                            FR (Z_to_bv 64 AHUF_DX2_4X) fc None m0 (seg_rom bsegs)).
Proof using All.
  intros t0 t1 t2 a6 a7 t3 t4 t5 t6 flags SRC0 CBS0 HDR0 ST MI FL.
  pose proof z4e_sp as SPB. pose proof (AI_layout AI _ _ _ _ _ AH) as (LY1 & LY2 & LY3 & _).
  pose proof z4e_blocks as (B1 & B2 & B3 & B4 & _). unfold AIMG_HI in B1.
  pose proof ATOP_range as ATR. unfold ATOP_MIN, ATOP_MAX in ATR.
  pose proof z4e_fast_pre as (FP1 & FP2 & FP3 & FP4 & FP5 & FP6 & FP7 & FP8 & FPS).
  pose proof (AI_rtcells AI _ _ _ _ _ AH) as (_ & GOT & _ & _ & SHB & _).
  unfold HUF_DEC_STACK_A in LOS.
  pose proof (conj SRC0 (conj CBS0 HDR0)) as KEEP. clear SRC0 CBS0 HDR0.
  pose proof (munch_refl DW m0) as MU. pose proof (wmono_refl bsegs m0) as WM.
  match goal with |- context [Z_to_bv 64 AHUF_DX2_4X] => let v := eval vm_compute in AHUF_DX2_4X in change AHUF_DX2_4X with v end.
  zstep.
  carve_frame 104%nat ST. carve_frame 128%nat ST. carve_frame 152%nat ST. carve_frame 144%nat ST.
  do 16 zstep.
  zstep. if_cases K68; zify_cond K68;
    [| zstep;
       lazymatch goal with
       | H1 : rw_cells _ ?m (bv_unsigned sp + -528) ?c1, H2 : rw_cells _ ?m (bv_unsigned sp + -384) ?c2,
         H3 : rw_cells _ ?m (bv_unsigned sp + -232) ?c3, MU' : munch _ m0 ?m |- _ =>
           destruct (z4e_join3 m c1 c2 c3 H1 eq_refl H2 eq_refl H3 eq_refl) as (jk & JK);
           destruct KEEP as (SRCk & CBSk & HDRk);
           destruct (z4e_mem3 m MU' SRCk CBSk HDRk) as (SRC1 & CBS1 & HDR1)
       end;
       let t1 := eval vm_compute in (AZ4_DRET - 12) in change (Z_to_bv 64 t1) with (Z_to_bv 64 (AZ4_DRET - 12));
       eapply z4e_dcall; eassumption ].
  do 7 zstep.
  zstep. if_cases K104; zify_cond K104; [| exfalso; z4land; lia].
  do 7 zstep.
  zstep. if_cases K140; zify_cond K140;
    [ lazymatch goal with
      | F : rw_cells _ ?m (bv_unsigned sp + -528) [?c0; ?c1; ?c2; ?c3; ?c4; ?c5; C8 (Z_to_bv 64 DST); ?c7; ?c8; ?c9] |- _ =>
          assert (F' : rw_cells bsegs m (bv_unsigned sp + -528)
                         [c0; c1; c2; c3; c4; c5; C8 (Z_to_bv 64 (DST + dcap)); c7; c8; c9])
            by (replace (DST + dcap) with DST by lia; exact F);
          clear F
      end
    | do 2 zstep;
      zstep; if_cases K152; zify_cond K152; [| exfalso; z4land; lia];
      zstep; if_cases K160; zify_cond K160; [| exfalso; z4land; lia];
      zstep;
      zstep; if_cases K172; zify_cond K172; [| exfalso; z4land; lia] ].
  all: do 10 zstep.
  all: destruct KEEP as (SRCk & CBSk & HDRk).
  all: eapply z4e_fa; first [eassumption | (unfold Z4F0; cbn [app]; eassumption) | reflexivity | (f_equal; lia)].
Qed.

